using Microsoft.AspNetCore.Authorization;using Microsoft.AspNetCore.Identity;using Microsoft.AspNetCore.Mvc;using Microsoft.EntityFrameworkCore;using Staybnb.Data;using Staybnb.Models;using Staybnb.Services;using Staybnb.ViewModels;using System.Text.Json;
namespace Staybnb.Controllers;
[Authorize(Roles="Host")]
public class HostController(ApplicationDbContext db,UserManager<ApplicationUser> users,ActivityLogger logger,NotificationService notifications,SecureFileStorage storage):Controller {
 public async Task<IActionResult> Index(){var uid=users.GetUserId(User)!;var props=await db.Properties.Where(p=>p.UserId==uid).ToListAsync();ViewBag.Properties=props.Count;ViewBag.Active=props.Count(p=>p.IsActive);ViewBag.Pending=await db.Bookings.CountAsync(b=>b.Property!.UserId==uid&&b.Status==WorkflowStatus.Pending);ViewBag.Approved=await db.Bookings.CountAsync(b=>b.Property!.UserId==uid&&b.Status==WorkflowStatus.Approved);return View(props);}
 [HttpGet] public async Task<IActionResult> EditProperty(int id){var uid=users.GetUserId(User)!;var p=await db.Properties.FirstOrDefaultAsync(p=>p.Id==id&&p.UserId==uid);if(p==null)return NotFound();return View(new HostPropertyEditViewModel{Id=p.Id,Title=p.Title,Description=p.Description,PricePerNight=p.PricePerNight,CleaningFee=p.CleaningFee,ServiceFee=p.ServiceFee,Capacity=p.Capacity,Address=p.Address,City=p.City,PropertyType=p.PropertyType});}
 [HttpPost,ValidateAntiForgeryToken] public async Task<IActionResult> EditProperty(HostPropertyEditViewModel vm){var uid=users.GetUserId(User)!;var p=await db.Properties.Include(p=>p.Images).FirstOrDefaultAsync(p=>p.Id==vm.Id&&p.UserId==uid);if(p==null)return NotFound();if(vm.NewImages.Count>10)ModelState.AddModelError(nameof(vm.NewImages),"Upload no more than 10 images at once.");if(!ModelState.IsValid)return View(vm);try{p.Title=vm.Title;p.Description=vm.Description;p.PricePerNight=vm.PricePerNight;p.CleaningFee=vm.CleaningFee;p.ServiceFee=vm.ServiceFee;p.Capacity=vm.Capacity;p.Address=vm.Address;p.City=vm.City;p.PropertyType=vm.PropertyType;foreach(var f in vm.NewImages){var url=await storage.SavePropertyImageAsync(f);p.Images.Add(new PropertyImage{ImageUrl=url,IsPrimary=p.Images.Count==0});}await db.SaveChangesAsync();await logger.LogAsync(uid,"Updated property #"+p.Id,"Property");TempData["Success"]="Property details saved.";return RedirectToAction(nameof(Index));}catch(InvalidOperationException ex){ModelState.AddModelError(nameof(vm.NewImages),ex.Message);return View(vm);}}
 [HttpPost,ValidateAntiForgeryToken] public async Task<IActionResult> ToggleActive(int id){var uid=users.GetUserId(User)!;var p=await db.Properties.Include(p=>p.HostApplication).FirstOrDefaultAsync(p=>p.Id==id&&p.UserId==uid);if(p==null)return NotFound();if(p.HostApplication?.Status!=WorkflowStatus.Approved)return BadRequest("Only approved properties can be activated.");p.IsActive=!p.IsActive;await db.SaveChangesAsync();await logger.LogAsync(uid,(p.IsActive?"Activated":"Deactivated")+" property #"+id,"Property");TempData["Success"]=p.IsActive?"Listing activated.":"Listing deactivated.";return RedirectToAction(nameof(Index));}
 public async Task<IActionResult> Bookings(){var uid=users.GetUserId(User)!;return View(await db.Bookings.Include(b=>b.Property).Include(b=>b.Guest).Where(b=>b.Property!.UserId==uid).OrderByDescending(b=>b.CreatedAt).ToListAsync());}
 [HttpPost,ValidateAntiForgeryToken] public async Task<IActionResult> DecideBooking(int id,string decision){var uid=users.GetUserId(User)!;var b=await db.Bookings.Include(x=>x.Property).FirstOrDefaultAsync(x=>x.Id==id&&x.Property!.UserId==uid);if(b==null)return NotFound();if(b.Status!=WorkflowStatus.Pending){TempData["Error"]="Only pending bookings can be decided.";return RedirectToAction(nameof(Bookings));}if(decision=="approve"){var conflict=await db.Bookings.AnyAsync(x=>x.Id!=id&&x.PropertyId==b.PropertyId&&x.Status==WorkflowStatus.Approved&&b.CheckInDate<x.CheckOutDate&&b.CheckOutDate>x.CheckInDate);if(conflict){TempData["Error"]="Those dates conflict with another approved booking.";return RedirectToAction(nameof(Bookings));}b.Status=WorkflowStatus.Approved;if(!await db.GuestCheckins.AnyAsync(x=>x.BookingId==b.Id)&&b.Property!.CheckInProcess!=null)db.GuestCheckins.Add(new GuestCheckin{BookingId=b.Id,CheckInProcessId=b.Property.CheckInProcess.Id});}else if(decision=="reject")b.Status=WorkflowStatus.Rejected;else return BadRequest();await db.SaveChangesAsync();await logger.LogAsync(uid,$"{decision}d booking #{id}","Booking");await notifications.AddAsync(b.GuestId,$"Booking #{id} was {b.Status}","Booking",$"/Bookings/Details/{id}");return RedirectToAction(nameof(Bookings));}
 public async Task<IActionResult> Documents(int? bookingId){var uid=users.GetUserId(User)!;var q=db.GuestDocuments.Include(d=>d.GuestCheckin!).ThenInclude(c=>c.Booking!).ThenInclude(b=>b.Property).Include(d=>d.GuestCheckin!).ThenInclude(c=>c.Booking!).ThenInclude(b=>b.Guest).Where(d=>d.GuestCheckin!.Booking!.Property!.UserId==uid);if(bookingId.HasValue)q=q.Where(d=>d.GuestCheckin!.BookingId==bookingId.Value);return View(await q.OrderBy(d=>d.Status).ToListAsync());}
 public async Task<IActionResult> CheckInProcesses(){var uid=users.GetUserId(User)!;return View(await db.Properties.Include(p=>p.CheckInProcess).Where(p=>p.UserId==uid).ToListAsync());}
 [HttpGet] public async Task<IActionResult> ConfigureCheckIn(int propertyId){var uid=users.GetUserId(User)!;var p=await db.Properties.Include(p=>p.CheckInProcess).FirstOrDefaultAsync(p=>p.Id==propertyId&&p.UserId==uid);if(p==null)return NotFound();var c=p.CheckInProcess;return View(new CheckInProcessViewModel{PropertyId=p.Id,Title=c?.Title??"Guest check-in",Steps=c==null?"Review instructions\nUpload required document":string.Join("\n",JsonSerializer.Deserialize<List<string>>(c.StepsJson)??new()),RequiredDocuments=c==null?"ID or passport":string.Join("\n",JsonSerializer.Deserialize<List<string>>(c.RequiredDocumentsJson)??new())});}
 [HttpPost,ValidateAntiForgeryToken] public async Task<IActionResult> ConfigureCheckIn(CheckInProcessViewModel vm){var uid=users.GetUserId(User)!;var p=await db.Properties.Include(p=>p.CheckInProcess).FirstOrDefaultAsync(p=>p.Id==vm.PropertyId&&p.UserId==uid);if(p==null)return NotFound();if(!ModelState.IsValid)return View(vm);var c=p.CheckInProcess??new CheckInProcess{PropertyId=p.Id};c.Title=vm.Title;c.StepsJson=JsonSerializer.Serialize(vm.Steps.Split((char)10,StringSplitOptions.TrimEntries|StringSplitOptions.RemoveEmptyEntries));c.RequiredDocumentsJson=JsonSerializer.Serialize(vm.RequiredDocuments.Split((char)10,StringSplitOptions.TrimEntries|StringSplitOptions.RemoveEmptyEntries));if(p.CheckInProcess==null)db.CheckInProcesses.Add(c);await db.SaveChangesAsync();await logger.LogAsync(uid,"Updated check-in process for property #"+p.Id,"CheckIn");return RedirectToAction(nameof(CheckInProcesses));}
}
